/* weoc-ui docs i18n — forms */
(function () {
  if (!window.WUI || !window.WUI.i18n) return;
  WUI.i18n.register([
    { lang:'en', id:'docs_forms_1', value:'Inputs' }, { lang:'ar', id:'docs_forms_1', value:'حقول الإدخال' },
    { lang:'en', id:'docs_forms_2', value:'Text Inputs & Fields' }, { lang:'ar', id:'docs_forms_2', value:'حقول الإدخال النصية والحقول' },
    { lang:'en', id:'docs_forms_3', value:'Input-view primitives from <code>weoc-forms.css</code>: the <code>form-control</code> input/textarea, the <code>wui-fieldset</code> group, the <code>field-row</code>/<code>field-item</code> grid, helper text, and the <code>wui-ftr-*</code> form footer. Every state and layout is shown below with its exact markup.' }, { lang:'ar', id:'docs_forms_3', value:'عناصر واجهة الإدخال الأساسية من <code>weoc-forms.css</code>: عنصر التحكم <code>form-control</code> للإدخال ومنطقة النص، ومجموعة <code>wui-fieldset</code>، وشبكة <code>field-row</code>/<code>field-item</code>، والنص المساعد، وتذييل النموذج <code>wui-ftr-*</code>. كل حالة وتخطيط معروض أدناه مع الترميز الدقيق الخاص به.' },
    { lang:'en', id:'docs_forms_4', value:'Add-on module — load weoc-forms.css on input views' }, { lang:'ar', id:'docs_forms_4', value:'وحدة إضافية: قم بتحميل weoc-forms.css على واجهات الإدخال' },
    { lang:'en', id:'docs_forms_5', value:'Forms are not in <code>weoc-ui-core.css</code>. Add <code>&lt;link rel="stylesheet" href="weoc-forms.css"&gt;</code> after the core barrel on input-style views. Checkboxes, radios, and card options live in <code>weoc-card-group.css</code> (see <a class="wui-link" href="./cards.html">Cards &amp; Forms</a>); TomSelect and Flatpickr have their own pages.' }, { lang:'ar', id:'docs_forms_5', value:'النماذج ليست ضمن <code>weoc-ui-core.css</code>. أضِف <code>&lt;link rel="stylesheet" href="weoc-forms.css"&gt;</code> بعد الحزمة الأساسية في واجهات نمط الإدخال. توجد مربعات الاختيار وأزرار الاختيار وخيارات البطاقات في <code>weoc-card-group.css</code> (راجع <a class="wui-link" href="./cards.html">Cards &amp; Forms</a>)؛ ولكل من TomSelect وFlatpickr صفحاته الخاصة.' },
    { lang:'en', id:'docs_forms_6', value:'<span class="material-symbols-outlined">text_fields</span>form-control' }, { lang:'ar', id:'docs_forms_6', value:'<span class="material-symbols-outlined">text_fields</span>form-control' },
    { lang:'en', id:'docs_forms_7', value:'Base class for text inputs and textareas (<code>height: 2.5rem</code>, transparent background, bordered). Focus draws a primary ring. <code>textarea.form-control</code> auto-grows in height and is vertically resizable (<code>min-height: 90px</code>). Readonly and disabled states are documented in their own sections below.' }, { lang:'ar', id:'docs_forms_7', value:'الصنف الأساسي لحقول الإدخال النصية ومناطق النص (<code>height: 2.5rem</code>، خلفية شفافة، محاط بإطار). التركيز يرسم حلقة بلون أساسي. تنمو <code>textarea.form-control</code> في الارتفاع تلقائيًا وقابلة لتغيير الحجم عموديًا (<code>min-height: 90px</code>). حالتا للقراءة فقط والمعطّل موثّقتان في أقسامهما الخاصة أدناه.' },
    { lang:'en', id:'docs_forms_8', value:'Text input — default & focus' }, { lang:'ar', id:'docs_forms_8', value:'إدخال نصي: الوضع الافتراضي والتركيز' },
    { lang:'en', id:'docs_forms_9', value:'Input types — <code>form-control</code> applies to all text-family inputs' }, { lang:'ar', id:'docs_forms_9', value:'أنواع الإدخال: <code>form-control</code> ينطبق على جميع حقول الإدخال النصية' },
    { lang:'en', id:'docs_forms_10', value:'<code>form-control</code> is type-agnostic: apply it to any single-line <code>&lt;input&gt;</code>. These render identically to a text field but keep their native keyboards and validation. Number fields get a themed stepper — see <code>wui-number</code> below.' }, { lang:'ar', id:'docs_forms_10', value:'<code>form-control</code> مستقل عن النوع: طبّقه على أي <code>&lt;input&gt;</code> من سطر واحد. تُعرض هذه بشكل مطابق للحقل النصي لكنها تحتفظ بلوحات المفاتيح والتحقق الأصليين. تحصل الحقول الرقمية على مُدرِّج بنمط السمة، راجع <code>wui-number</code> أدناه.' },
    { lang:'en', id:'docs_forms_11', value:'Textarea' }, { lang:'ar', id:'docs_forms_11', value:'منطقة نص' },
    { lang:'en', id:'docs_forms_12', value:'<span class="material-symbols-outlined">123</span>wui-number — themed stepper' }, { lang:'ar', id:'docs_forms_12', value:'<span class="material-symbols-outlined">123</span>wui-number: مُدرِّج بنمط السمة' },
    { lang:'en', id:'docs_forms_13', value:'Browsers render native <code>type="number"</code> spinners in their own chrome that cannot be recoloured to match the theme (WebKit exposes almost nothing; Firefox nothing). <code>wui-number</code> wraps the input, hides the native spinners, and adds token-driven <code>+</code>/<code>−</code> buttons that follow light and dark automatically. <code>weoc-ui.js</code> binds <code>data-wui-step</code> and steps the input with the native <code>stepUp()</code>/<code>stepDown()</code>, so <code>min</code>, <code>max</code>, and <code>step</code> are honoured and <code>input</code>/<code>change</code> events still fire. The input stays keyboard-steppable (arrow keys); the buttons are <code>tabindex="-1"</code> mouse aids. Requires <code>weoc-ui.js</code>.' }, { lang:'ar', id:'docs_forms_13', value:'تعرض المتصفحات أدوات الزيادة والنقصان الأصلية لـ <code>type="number"</code> ضمن واجهتها الخاصة التي لا يمكن إعادة تلوينها لتطابق السمة (WebKit لا يتيح شيئًا يُذكر؛ وFirefox لا يتيح شيئًا). يغلّف <code>wui-number</code> حقل الإدخال، ويخفي أدوات الزيادة الأصلية، ويضيف زرَّي <code>+</code>/<code>−</code> مُدارَين بالرموز يتبعان الوضعين الفاتح والداكن تلقائيًا. يربط <code>weoc-ui.js</code> السمة <code>data-wui-step</code> ويُدرِّج الحقل باستخدام <code>stepUp()</code>/<code>stepDown()</code> الأصليين، بحيث تُحترم <code>min</code> و<code>max</code> و<code>step</code> ولا تزال أحداث <code>input</code>/<code>change</code> تُطلَق. يبقى الحقل قابلاً للتدريج بلوحة المفاتيح (مفاتيح الأسهم)؛ والأزرار مساعدات ماوس بقيمة <code>tabindex="-1"</code>. يتطلب <code>weoc-ui.js</code>.' },
    { lang:'en', id:'docs_forms_14', value:'Default — with value, min / max / step' }, { lang:'ar', id:'docs_forms_14', value:'الافتراضي: بقيمة، مع min / max / step' },
    { lang:'en', id:'docs_forms_15', value:'Readonly & disabled — stepper hidden, padding reclaimed' }, { lang:'ar', id:'docs_forms_15', value:'للقراءة فقط والمعطّل: المُدرِّج مخفي، والحشو مُستعاد' },
    { lang:'en', id:'docs_forms_16', value:'<span class="material-symbols-outlined">tune</span>wui-fieldset' }, { lang:'ar', id:'docs_forms_16', value:'<span class="material-symbols-outlined">tune</span>wui-fieldset' },
    { lang:'en', id:'docs_forms_17', value:'A titled section grouping field rows. <code>wui-fieldset-legend</code> (optional icon) sits at the top, an optional <code>wui-fieldset-sub</code> description tucks under it, and <code>wui-fieldset-body</code> holds the <code>field-row</code> groups. Works on a real <code>&lt;fieldset&gt;</code>/<code>&lt;legend&gt;</code> or plain divs. Add <code>plain</code> to drop the surface chrome (background, border, padding).' }, { lang:'ar', id:'docs_forms_17', value:'قسم بعنوان يجمّع صفوف الحقول. يقع <code>wui-fieldset-legend</code> (أيقونة اختيارية) في الأعلى، ويندرج تحته وصف اختياري <code>wui-fieldset-sub</code>، ويحتوي <code>wui-fieldset-body</code> على مجموعات <code>field-row</code>. يعمل على <code>&lt;fieldset&gt;</code>/<code>&lt;legend&gt;</code> حقيقيين أو على عناصر div عادية. أضِف <code>plain</code> لإزالة زخرفة السطح (الخلفية والإطار والحشو).' },
    { lang:'en', id:'docs_forms_18', value:'Standard fieldset (legend + sub + body)' }, { lang:'ar', id:'docs_forms_18', value:'مجموعة حقول قياسية (legend + sub + body)' },
    { lang:'en', id:'docs_forms_19', value:'Plain (no chrome)' }, { lang:'ar', id:'docs_forms_19', value:'عادي (بلا زخرفة)' },
    { lang:'en', id:'docs_forms_20', value:'<span class="material-symbols-outlined">grid_view</span>Field grid — field-row / field-item' }, { lang:'ar', id:'docs_forms_20', value:'<span class="material-symbols-outlined">grid_view</span>شبكة الحقول: field-row / field-item' },
    { lang:'en', id:'docs_forms_21', value:'<code>field-row</code> is a CSS grid. By default it is 2 columns; add <code>full</code> for 1 column, <code>three</code> for 3, or <code>four</code> for 4. Each <code>field-item</code> is a vertical stack of <code>field-label</code> → control → optional <code>field-hint</code>. <code>field-label .required</code> renders a danger-colored asterisk. A label may carry a leading <code>material-symbols-outlined</code> icon (tinted primary).' }, { lang:'ar', id:'docs_forms_21', value:'<code>field-row</code> شبكة CSS. تكون افتراضيًا من عمودين؛ أضِف <code>full</code> لعمود واحد، أو <code>three</code> لثلاثة، أو <code>four</code> لأربعة. كل <code>field-item</code> هو تكديس عمودي من <code>field-label</code> ← عنصر التحكم ← <code>field-hint</code> اختياري. يعرض <code>field-label .required</code> علامة نجمية بلون الخطر. قد تحمل التسمية أيقونة <code>material-symbols-outlined</code> في المقدمة (مُلوَّنة باللون الأساسي).' },
    { lang:'en', id:'docs_forms_22', value:'field-row — 2 columns (default)' }, { lang:'ar', id:'docs_forms_22', value:'field-row: عمودان (افتراضي)' },
    { lang:'en', id:'docs_forms_23', value:'field-row full — 1 column' }, { lang:'ar', id:'docs_forms_23', value:'field-row full: عمود واحد' },
    { lang:'en', id:'docs_forms_24', value:'field-row three — 3 columns' }, { lang:'ar', id:'docs_forms_24', value:'field-row three: ثلاثة أعمدة' },
    { lang:'en', id:'docs_forms_25', value:'field-row four — 4 columns' }, { lang:'ar', id:'docs_forms_25', value:'field-row four: أربعة أعمدة' },
    { lang:'en', id:'docs_forms_26', value:'field-label — required marker & icon' }, { lang:'ar', id:'docs_forms_26', value:'field-label: علامة الإلزام والأيقونة' },
    { lang:'en', id:'docs_forms_27', value:'field-hint — helper text' }, { lang:'ar', id:'docs_forms_27', value:'field-hint: النص المساعد' },
    { lang:'en', id:'docs_forms_28', value:'<span class="material-symbols-outlined">lock</span>Readonly fields' }, { lang:'ar', id:'docs_forms_28', value:'<span class="material-symbols-outlined">lock</span>حقول للقراءة فقط' },
    { lang:'en', id:'docs_forms_29', value:'Use the native <code>[readonly]</code> attribute or the <code>.is-readonly</code> class on the control for fields that display existing data and must not be edited. Both selectors produce the same look: a dashed border and a muted secondary-light surface. The text stays copyable and the field is still focusable. Wrapping <code>field-item</code> in <code>is-readonly</code> also dims the label. (Readonly is not disabled — see the callout below.)' }, { lang:'ar', id:'docs_forms_29', value:'استخدم السمة الأصلية <code>[readonly]</code> أو الصنف <code>.is-readonly</code> على عنصر التحكم للحقول التي تعرض بيانات موجودة ويجب ألا تُحرَّر. ينتج المُحدِّدان المظهر نفسه: إطار متقطّع وسطح ثانوي فاتح خافت. يبقى النص قابلاً للنسخ ويظل الحقل قابلاً للتركيز. تغليف <code>field-item</code> بالصنف <code>is-readonly</code> يخفت أيضًا التسمية. (للقراءة فقط ليس معطّلاً، راجع التنبيه أدناه.)' },
    { lang:'en', id:'docs_forms_30', value:'[readonly] attribute vs .is-readonly class' }, { lang:'ar', id:'docs_forms_30', value:'السمة [readonly] مقابل الصنف .is-readonly' },
    { lang:'en', id:'docs_forms_31', value:'Readonly textarea (resize disabled)' }, { lang:'ar', id:'docs_forms_31', value:'منطقة نص للقراءة فقط (تغيير الحجم معطّل)' },
    { lang:'en', id:'docs_forms_32', value:'Editable vs readonly — side by side' }, { lang:'ar', id:'docs_forms_32', value:'قابل للتحرير مقابل للقراءة فقط: جنبًا إلى جنب' },
    { lang:'en', id:'docs_forms_33', value:'Readonly ≠ disabled' }, { lang:'ar', id:'docs_forms_33', value:'للقراءة فقط ≠ معطّل' },
    { lang:'en', id:'docs_forms_34', value:'Readonly fields are still focusable and the text is copyable. If the control must be completely inert (no tab stop, grayed out), use the <code>disabled</code> attribute instead (next section).' }, { lang:'ar', id:'docs_forms_34', value:'تبقى الحقول للقراءة فقط قابلة للتركيز ونصها قابل للنسخ. إذا وجب أن يكون عنصر التحكم خاملاً تمامًا (بلا محطة جدولة، ومُعتّم)، فاستخدم السمة <code>disabled</code> بدلاً من ذلك (القسم التالي).' },
    { lang:'en', id:'docs_forms_35', value:'<span class="material-symbols-outlined">block</span>Disabled fields' }, { lang:'ar', id:'docs_forms_35', value:'<span class="material-symbols-outlined">block</span>حقول معطّلة' },
    { lang:'en', id:'docs_forms_36', value:'The native <code>disabled</code> attribute renders inert controls. <code>form-control</code> inherits the browser\'s default disabled treatment (reduced contrast, no focus, no tab stop). Use disabled when the field should not be interactive at all; use readonly when its value should still be selectable and copyable.' }, { lang:'ar', id:'docs_forms_36', value:'تعرض السمة الأصلية <code>disabled</code> عناصر تحكم خاملة. يرث <code>form-control</code> معالجة التعطيل الافتراضية للمتصفح (تباين مخفَّض، بلا تركيز، بلا محطة جدولة). استخدم المعطّل عندما يجب ألا يكون الحقل تفاعليًا على الإطلاق؛ واستخدم للقراءة فقط عندما يجب أن تبقى قيمته قابلة للتحديد والنسخ.' },
    { lang:'en', id:'docs_forms_37', value:'Disabled input & textarea' }, { lang:'ar', id:'docs_forms_37', value:'حقل إدخال ومنطقة نص معطّلان' },
    { lang:'en', id:'docs_forms_38', value:'<span class="material-symbols-outlined">view_agenda</span>form-section' }, { lang:'ar', id:'docs_forms_38', value:'<span class="material-symbols-outlined">view_agenda</span>form-section' },
    { lang:'en', id:'docs_forms_39', value:'A carded surface with a titled header, used to break a long form into labelled blocks. <code>form-section-title</code> is an underlined heading with an optional leading icon (tinted primary). Similar to <code>wui-fieldset</code> but without a semantic <code>&lt;legend&gt;</code>; use it for lighter visual grouping.' }, { lang:'ar', id:'docs_forms_39', value:'سطح بهيئة بطاقة برأس بعنوان، يُستخدم لتقسيم نموذج طويل إلى كتل معنونة. <code>form-section-title</code> عنوان مُسطَّر بأيقونة اختيارية في المقدمة (مُلوَّنة باللون الأساسي). مشابه لـ <code>wui-fieldset</code> لكن بلا <code>&lt;legend&gt;</code> دلالي؛ استخدمه لتجميع بصري أخف.' },
    { lang:'en', id:'docs_forms_40', value:'Titled section' }, { lang:'ar', id:'docs_forms_40', value:'قسم بعنوان' },
    { lang:'en', id:'docs_forms_41', value:'<span class="material-symbols-outlined">dock_to_bottom</span>wui-ftr-wrap — form footer' }, { lang:'ar', id:'docs_forms_41', value:'<span class="material-symbols-outlined">dock_to_bottom</span>wui-ftr-wrap: تذييل النموذج' },
    { lang:'en', id:'docs_forms_42', value:'Sticky action bar for input views. <code>wui-ftr-wrap</code> → <code>wui-ftr-inner</code> → <code>wui-ftr-body</code> lays out a left meta zone (<code>wui-ftr-left</code> / <code>wui-ftr-meta</code>) and a right action zone (<code>wui-ftr-right</code> or <code>wui-ftr-actions</code>). <code>wui-ftr-meta</code> takes a status modifier (<code>primary</code> / <code>success</code> / <code>warning</code> / <code>danger</code>) that tints its icon, and <code>&lt;strong&gt;</code> inside it is emphasized. Add <code>centered</code> to the wrap for a max-width carded footer, or <code>actions-only</code> to the body when there is no meta zone so the buttons stay right-aligned.' }, { lang:'ar', id:'docs_forms_42', value:'شريط إجراءات ملتصق لواجهات الإدخال. يوزّع <code>wui-ftr-wrap</code> → <code>wui-ftr-inner</code> → <code>wui-ftr-body</code> منطقة بيانات وصفية يسارية (<code>wui-ftr-left</code> / <code>wui-ftr-meta</code>) ومنطقة إجراءات يمينية (<code>wui-ftr-right</code> أو <code>wui-ftr-actions</code>). يأخذ <code>wui-ftr-meta</code> مُعدِّل حالة (<code>primary</code> / <code>success</code> / <code>warning</code> / <code>danger</code>) يُلوِّن أيقونته، ويكون <code>&lt;strong&gt;</code> بداخله مُبرَزًا. أضِف <code>centered</code> إلى الغلاف للحصول على تذييل بهيئة بطاقة بعرض أقصى، أو <code>actions-only</code> إلى الجسم عند عدم وجود منطقة بيانات وصفية لتبقى الأزرار محاذاة لليمين.' },
    { lang:'en', id:'docs_forms_43', value:'Default footer — meta status colors' }, { lang:'ar', id:'docs_forms_43', value:'التذييل الافتراضي: ألوان حالة البيانات الوصفية' },
    { lang:'en', id:'docs_forms_44', value:'Meta modifiers — primary / warning / danger' }, { lang:'ar', id:'docs_forms_44', value:'مُعدِّلات البيانات الوصفية: primary / warning / danger' },
    { lang:'en', id:'docs_forms_45', value:'Centered — carded footer' }, { lang:'ar', id:'docs_forms_45', value:'موسّط: تذييل بهيئة بطاقة' },
    { lang:'en', id:'docs_forms_46', value:'Actions only — <code>actions-only</code> body (no meta)' }, { lang:'ar', id:'docs_forms_46', value:'إجراءات فقط: جسم <code>actions-only</code> (بلا بيانات وصفية)' },

    /* Date & Time (Flatpickr) — merged from the former dates.html */
    { lang:'en', id:'docs_forms_47', value:'<span class="material-symbols-outlined">calendar_month</span>Date &amp; Time (Flatpickr)' }, { lang:'ar', id:'docs_forms_47', value:'<span class="material-symbols-outlined">calendar_month</span>التاريخ والوقت (Flatpickr)' },
    { lang:'en', id:'docs_forms_48', value:'Date, time, datetime, and range pickers powered by <code>flatpickr-factory.js</code>. Add <code>data-fp-preset</code> to any <code>&lt;input&gt;</code> and the factory auto-inits it, styling it with <code>flatpickr-input</code> and the <code>flat-date</code> / <code>flat-time</code> / <code>flat-range-*</code> skins. Vendor CSS/JS are loaded globally by the docs shell.' }, { lang:'ar', id:'docs_forms_48', value:'منتقيات للتاريخ والوقت والتاريخ والوقت والنطاق مدعومة بواسطة <code>flatpickr-factory.js</code>. أضف <code>data-fp-preset</code> إلى أي <code>&lt;input&gt;</code> وسيقوم المصنع بتهيئته تلقائيًا، مع تنسيقه باستخدام <code>flatpickr-input</code> وأصناف <code>flat-date</code> / <code>flat-time</code> / <code>flat-range-*</code>. يتم تحميل ملفات CSS/JS الخاصة بالمورّد بشكل عام بواسطة غلاف التوثيق.' },
    { lang:'en', id:'docs_forms_49', value:'How the factory binds' }, { lang:'ar', id:'docs_forms_49', value:'كيفية ربط المصنع' },
    { lang:'en', id:'docs_forms_50', value:'The factory exposes the global <code>window.FlatpickrFactory</code> with <code>init(scope)</code>, <code>PRESETS</code>, and <code>FMT</code>. On load it calls <code>FlatpickrFactory.init()</code>, which runs <code>querySelectorAll(\'[data-fp-preset]\')</code> over the scope and initializes every matching input (already-initialized inputs carry <code>_flatpickr</code> and are skipped). Every input dispatches a bubbling <code>fp:change</code> CustomEvent (<code>e.detail.dateStr</code>) on selection.' }, { lang:'ar', id:'docs_forms_50', value:'يوفّر المصنع الكائن العام <code>window.FlatpickrFactory</code> مع <code>init(scope)</code> و<code>PRESETS</code> و<code>FMT</code>. عند التحميل يستدعي <code>FlatpickrFactory.init()</code>، الذي يشغّل <code>querySelectorAll(\'[data-fp-preset]\')</code> على النطاق ويهيّئ كل إدخال مطابق (الإدخالات المهيّأة مسبقًا تحمل <code>_flatpickr</code> ويتم تخطّيها). يرسل كل إدخال حدث <code>fp:change</code> من نوع CustomEvent (<code>e.detail.dateStr</code>) عند الاختيار.' },
    { lang:'en', id:'docs_forms_51', value:'Re-init after SPA navigation' }, { lang:'ar', id:'docs_forms_51', value:'إعادة التهيئة بعد التنقل في تطبيق الصفحة الواحدة' },
    { lang:'en', id:'docs_forms_52', value:'These demos are initialized by this page\'s own <code>Alpine.data(\'formsPage\', ...)</code> component (which calls <code>FlatpickrFactory.init()</code> from inside <code>window.DocShell.ready</code>), so they re-bind on every navigation to this page. The classes <code>flat-date</code> / <code>flat-time</code> / <code>flat-range-start</code> / <code>flat-range-end</code> are cosmetic only; binding is driven entirely by <code>data-fp-preset</code>.' }, { lang:'ar', id:'docs_forms_52', value:'تتم تهيئة هذه العروض التوضيحية بواسطة مكوّن <code>Alpine.data(\'formsPage\', ...)</code> الخاص بهذه الصفحة (الذي يستدعي <code>FlatpickrFactory.init()</code> من داخل <code>window.DocShell.ready</code>)، لذا تُعاد ربطها في كل تنقّل إلى هذه الصفحة. الأصناف <code>flat-date</code> / <code>flat-time</code> / <code>flat-range-start</code> / <code>flat-range-end</code> تجميلية فقط؛ يُدار الربط بالكامل عبر <code>data-fp-preset</code>.' },
    { lang:'en', id:'docs_forms_53', value:'<span class="material-symbols-outlined">calendar_today</span>Date only' }, { lang:'ar', id:'docs_forms_53', value:'<span class="material-symbols-outlined">calendar_today</span>التاريخ فقط' },
    { lang:'en', id:'docs_forms_54', value:'Calendar picker, no time. <code>date</code> renders ISO <code>Y-m-d</code>; <code>date-dmy</code> renders <code>d/m/Y</code>.' }, { lang:'ar', id:'docs_forms_54', value:'منتقي تقويم، بدون وقت. <code>date</code> يعرض بصيغة ISO <code>Y-m-d</code>؛ <code>date-dmy</code> يعرض <code>d/m/Y</code>.' },
    { lang:'en', id:'docs_forms_55', value:'date / date-dmy' }, { lang:'ar', id:'docs_forms_55', value:'date / date-dmy' },
    { lang:'en', id:'docs_forms_56', value:'<span class="material-symbols-outlined">schedule</span>Time only' }, { lang:'ar', id:'docs_forms_56', value:'<span class="material-symbols-outlined">schedule</span>الوقت فقط' },
    { lang:'en', id:'docs_forms_57', value:'<code>noCalendar</code> presets — the time spinner with no date. <code>time</code> is 24hr (<code>H:i</code>); <code>time-12</code> is 12hr with AM/PM (<code>h:i K</code>).' }, { lang:'ar', id:'docs_forms_57', value:'إعدادات <code>noCalendar</code>: مؤشر الوقت الدوّار بدون تاريخ. <code>time</code> بنظام 24 ساعة (<code>H:i</code>)؛ <code>time-12</code> بنظام 12 ساعة مع AM/PM (<code>h:i K</code>).' },
    { lang:'en', id:'docs_forms_58', value:'time / time-12' }, { lang:'ar', id:'docs_forms_58', value:'time / time-12' },
    { lang:'en', id:'docs_forms_59', value:'<span class="material-symbols-outlined">event</span>Date + time' }, { lang:'ar', id:'docs_forms_59', value:'<span class="material-symbols-outlined">event</span>التاريخ والوقت' },
    { lang:'en', id:'docs_forms_60', value:'<code>enableTime</code> presets combining calendar and clock. Format and 12/24hr vary per preset; <code>datetime-seconds</code> adds a seconds spinner.' }, { lang:'ar', id:'docs_forms_60', value:'إعدادات <code>enableTime</code> تجمع بين التقويم والساعة. تختلف الصيغة ونظام 12/24 ساعة حسب كل إعداد؛ <code>datetime-seconds</code> يضيف مؤشر ثوانٍ دوّار.' },
    { lang:'en', id:'docs_forms_61', value:'datetime / datetime-dmy / datetime-12 / datetime-seconds' }, { lang:'ar', id:'docs_forms_61', value:'datetime / datetime-dmy / datetime-12 / datetime-seconds' },
    { lang:'en', id:'docs_forms_62', value:'<span class="material-symbols-outlined">history_toggle_off</span>Future-only &amp; past-only' }, { lang:'ar', id:'docs_forms_62', value:'<span class="material-symbols-outlined">history_toggle_off</span>المستقبل فقط والماضي فقط' },
    { lang:'en', id:'docs_forms_63', value:'Bounded presets that clamp the selectable range against <em>now</em>. The min/max is refreshed in an <code>onOpen</code> hook so the boundary stays accurate across a long-lived page. <code>past-datetime</code> also adds 12hr time + seconds.' }, { lang:'ar', id:'docs_forms_63', value:'إعدادات محدودة تقيّد النطاق القابل للاختيار مقابل <em>الآن</em>. يتم تحديث الحد الأدنى/الأقصى في خطاف <code>onOpen</code> حتى يبقى الحدّ دقيقًا عبر صفحة طويلة الأمد. <code>past-datetime</code> يضيف أيضًا وقتًا بنظام 12 ساعة مع الثواني.' },
    { lang:'en', id:'docs_forms_64', value:'future-date / past-date' }, { lang:'ar', id:'docs_forms_64', value:'future-date / past-date' },
    { lang:'en', id:'docs_forms_65', value:'future-datetime / past-datetime' }, { lang:'ar', id:'docs_forms_65', value:'future-datetime / past-datetime' },
    { lang:'en', id:'docs_forms_66', value:'<span class="material-symbols-outlined">date_range</span>Date range (paired)' }, { lang:'ar', id:'docs_forms_66', value:'<span class="material-symbols-outlined">date_range</span>نطاق التاريخ (مقترن)' },
    { lang:'en', id:'docs_forms_67', value:'Two inputs that constrain each other: both share a <code>data-fp-range-group</code>, with <code>data-fp-range-role="start"</code> on one and <code>"end"</code> on the other. The start\'s selection becomes the end\'s minimum and vice-versa. Wrap the pair in <code>wui-date-range-wrap</code> for the tight flex row.' }, { lang:'ar', id:'docs_forms_67', value:'إدخالان يقيّد كل منهما الآخر: يتشاركان <code>data-fp-range-group</code>، مع <code>data-fp-range-role="start"</code> على أحدهما و<code>"end"</code> على الآخر. يصبح اختيار البداية الحدّ الأدنى للنهاية والعكس صحيح. لُفّ الزوج داخل <code>wui-date-range-wrap</code> للحصول على صف flex متضام.' },
    { lang:'en', id:'docs_forms_68', value:'range-start + range-end' }, { lang:'ar', id:'docs_forms_68', value:'range-start + range-end' },
    { lang:'en', id:'docs_forms_69', value:'<span class="material-symbols-outlined">calendar_month</span>Inline calendar' }, { lang:'ar', id:'docs_forms_69', value:'<span class="material-symbols-outlined">calendar_month</span>تقويم مضمّن' },
    { lang:'en', id:'docs_forms_70', value:'<code>data-fp-inline="true"</code> embeds the calendar permanently in place instead of opening a popup. Works with any preset; useful for date panels and dashboard filter widgets.' }, { lang:'ar', id:'docs_forms_70', value:'<code>data-fp-inline="true"</code> يضمّن التقويم بشكل دائم في مكانه بدلاً من فتح نافذة منبثقة. يعمل مع أي إعداد؛ مفيد للوحات التاريخ وأدوات تصفية لوحات المعلومات.' },
    { lang:'en', id:'docs_forms_71', value:'date · inline' }, { lang:'ar', id:'docs_forms_71', value:'date · inline' },
    { lang:'en', id:'docs_forms_72', value:'<span class="material-symbols-outlined">tune</span>Per-input overrides' }, { lang:'ar', id:'docs_forms_72', value:'<span class="material-symbols-outlined">tune</span>تجاوزات لكل إدخال' },
    { lang:'en', id:'docs_forms_73', value:'Any preset can be tuned inline with <code>data-fp-*</code> overrides: <code>data-fp-format</code> (a <code>Y-m-d</code> string or an alias like <code>dmy-hi</code>), <code>data-fp-min-date</code> / <code>data-fp-max-date</code>, <code>data-fp-enable-time</code>, <code>data-fp-24hr</code>, <code>data-fp-seconds</code>, <code>data-fp-allow-input</code>, <code>data-fp-week-numbers</code>, <code>data-fp-mode</code> (<code>single</code>/<code>multiple</code>/<code>range</code>), <code>data-fp-position</code>, <code>data-fp-default-date</code>, and <code>data-fp-on-change</code> (name of a global handler).' }, { lang:'ar', id:'docs_forms_73', value:'يمكن ضبط أي إعداد بشكل مباشر باستخدام تجاوزات <code>data-fp-*</code>: <code>data-fp-format</code> (سلسلة <code>Y-m-d</code> أو اسم مستعار مثل <code>dmy-hi</code>)، <code>data-fp-min-date</code> / <code>data-fp-max-date</code>، <code>data-fp-enable-time</code>، <code>data-fp-24hr</code>، <code>data-fp-seconds</code>، <code>data-fp-allow-input</code>، <code>data-fp-week-numbers</code>، <code>data-fp-mode</code> (<code>single</code>/<code>multiple</code>/<code>range</code>)، <code>data-fp-position</code>، <code>data-fp-default-date</code>، و<code>data-fp-on-change</code> (اسم معالج عام).' },
    { lang:'en', id:'docs_forms_74', value:'Override examples' }, { lang:'ar', id:'docs_forms_74', value:'أمثلة على التجاوزات' },
    { lang:'en', id:'docs_forms_75', value:'<span class="material-symbols-outlined">lock</span>Readonly display' }, { lang:'ar', id:'docs_forms_75', value:'<span class="material-symbols-outlined">lock</span>عرض للقراءة فقط' },
    { lang:'en', id:'docs_forms_76', value:'Flatpickr always sets <code>[readonly]</code> internally. For a true display-only field, add <code>.is-readonly</code> to the input and disable opening with <code>fp.set(\'clickOpens\', false)</code>. The dashed border and muted surface match the form-control readonly language.' }, { lang:'ar', id:'docs_forms_76', value:'يضبط Flatpickr دائمًا <code>[readonly]</code> داخليًا. للحصول على حقل للعرض فقط بالكامل، أضف <code>.is-readonly</code> إلى الإدخال وعطّل الفتح باستخدام <code>fp.set(\'clickOpens\', false)</code>. يطابق الحدّ المتقطّع والسطح الباهت لغة القراءة فقط الخاصة بعنصر التحكم في النموذج.' },
    { lang:'en', id:'docs_forms_77', value:'Editable vs readonly' }, { lang:'ar', id:'docs_forms_77', value:'قابل للتحرير مقابل للقراءة فقط' },

    /* Select / Combobox (TomSelect) — merged from the former combobox.html */
    { lang:'en', id:'docs_forms_78', value:'<span class="material-symbols-outlined">arrow_drop_down_circle</span>Select / Combobox (TomSelect)' }, { lang:'ar', id:'docs_forms_78', value:'<span class="material-symbols-outlined">arrow_drop_down_circle</span>قائمة الاختيار / Combobox (TomSelect)' },
    { lang:'en', id:'docs_forms_79', value:'The <code>tom-select-factory.js</code> combobox. Add <code>class="tomselect"</code> to any <code>&lt;select&gt;</code>, drive every behavior through <code>data-*</code> attributes, and call <code>TomSelectFactory.init()</code>. The factory injects a blank placeholder option, resyncs dependent cascades, mounts pinned dropdown header/footer slots, and follows the agency theme. Every capability is demoed below with the exact markup and the exact init call.' }, { lang:'ar', id:'docs_forms_79', value:'قائمة الاختيار في <code>tom-select-factory.js</code>. أضف <code>class="tomselect"</code> إلى أي <code>&lt;select&gt;</code>، وتحكم في كل سلوك من خلال سمات <code>data-*</code>، ثم استدعِ <code>TomSelectFactory.init()</code>. يقوم المصنع بإدراج خيار عنصر نائب فارغ، ويعيد مزامنة القوائم المتسلسلة التابعة، ويثبّت فتحات رأس/تذييل القائمة المنسدلة المثبتة، ويتبع سمة الوكالة. يتم عرض كل إمكانية أدناه مع الترميز الدقيق واستدعاء التهيئة الدقيق.' },
    { lang:'en', id:'docs_forms_80', value:'How it initializes' }, { lang:'ar', id:'docs_forms_80', value:'كيفية التهيئة' },
    { lang:'en', id:'docs_forms_81', value:'The factory binds every <code>&lt;select class="tomselect"&gt;</code> in scope. Call <code>TomSelectFactory.init()</code> once after the DOM is ready. It also starts a <code>MutationObserver</code>, so late-injected selects (WebEOC repeat regions, modals) initialize automatically. Retrieve a live instance with <code>TomSelectFactory.get(\'idOrName\')</code>; drive it with <code>refresh</code>, <code>destroy</code>, <code>enable</code>, <code>disable</code>.' }, { lang:'ar', id:'docs_forms_81', value:'يربط المصنع كل <code>&lt;select class="tomselect"&gt;</code> ضمن النطاق. استدعِ <code>TomSelectFactory.init()</code> مرة واحدة بعد جاهزية الـ DOM. كما يبدأ <code>MutationObserver</code>، لذا تتم تهيئة قوائم الاختيار المُدرَجة لاحقًا (مناطق التكرار والنوافذ المنبثقة في WebEOC) تلقائيًا. استرجع نسخة نشطة باستخدام <code>TomSelectFactory.get(\'idOrName\')</code>، وتحكم فيها عبر <code>refresh</code> و<code>destroy</code> و<code>enable</code> و<code>disable</code>.' },
    { lang:'en', id:'docs_forms_82', value:'Load order' }, { lang:'ar', id:'docs_forms_82', value:'ترتيب التحميل' },
    { lang:'en', id:'docs_forms_83', value:'<code>tom-select.min.css</code> → <code>tom-select-agency.css</code> in <code>&lt;head&gt;</code>, then <code>tom-select.complete.min.js</code> → <code>tom-select-factory.js</code>. On this docs site the vendor CSS/JS is loaded site-wide by the shell; you only call <code>TomSelectFactory.init()</code>.' }, { lang:'ar', id:'docs_forms_83', value:'<code>tom-select.min.css</code> → <code>tom-select-agency.css</code> في <code>&lt;head&gt;</code>، ثم <code>tom-select.complete.min.js</code> → <code>tom-select-factory.js</code>. في موقع التوثيق هذا، يتم تحميل ملفات CSS/JS الخاصة بالمورّد على مستوى الموقع بالكامل عبر الهيكل؛ ما عليك سوى استدعاء <code>TomSelectFactory.init()</code>.' },
    { lang:'en', id:'docs_forms_84', value:'Instance key' }, { lang:'ar', id:'docs_forms_84', value:'مفتاح النسخة' },
    { lang:'en', id:'docs_forms_85', value:'The key is the select\'s <code>id</code>, or its <code>name</code> if there is no id (an auto <code>data-ts-key</code> is stamped only when both are absent). Use that key with <code>TomSelectFactory.get()</code> / <code>enable()</code> / <code>disable()</code> / <code>destroy()</code> / <code>refresh()</code>.' }, { lang:'ar', id:'docs_forms_85', value:'المفتاح هو <code>id</code> الخاص بقائمة الاختيار، أو <code>name</code> الخاص بها إذا لم يكن هناك id (تُختم سمة <code>data-ts-key</code> تلقائيًا فقط عند غياب كليهما). استخدم هذا المفتاح مع <code>TomSelectFactory.get()</code> / <code>enable()</code> / <code>disable()</code> / <code>destroy()</code> / <code>refresh()</code>.' },
    { lang:'en', id:'docs_forms_86', value:'<span class="material-symbols-outlined">arrow_drop_down_circle</span>Single select' }, { lang:'ar', id:'docs_forms_86', value:'<span class="material-symbols-outlined">arrow_drop_down_circle</span>اختيار مفرد' },
    { lang:'en', id:'docs_forms_87', value:'One item, with a built-in dropdown search field (<code>dropdown_input</code> plugin). The factory injects a blank placeholder option, so a fresh record shows the placeholder rather than auto-selecting the first real option. <code>data-placeholder</code> sets the placeholder text.' }, { lang:'ar', id:'docs_forms_87', value:'عنصر واحد، مع حقل بحث مدمج ضمن القائمة المنسدلة (الإضافة <code>dropdown_input</code>). يقوم المصنع بإدراج خيار عنصر نائب فارغ، لذا يعرض السجل الجديد العنصر النائب بدلًا من اختيار أول خيار حقيقي تلقائيًا. تحدد <code>data-placeholder</code> نص العنصر النائب.' },
    { lang:'en', id:'docs_forms_88', value:'Basic single (required — placeholder only)' }, { lang:'ar', id:'docs_forms_88', value:'اختيار مفرد أساسي (مطلوب: العنصر النائب فقط)' },
    { lang:'en', id:'docs_forms_89', value:'Without <code>data-allow-empty</code>, the placeholder shows on load but the user cannot re-select blank once a value is chosen. This is the correct pattern for required fields.' }, { lang:'ar', id:'docs_forms_89', value:'بدون <code>data-allow-empty</code>، يظهر العنصر النائب عند التحميل لكن لا يمكن للمستخدم إعادة اختيار القيمة الفارغة بعد اختيار قيمة. هذا هو النمط الصحيح للحقول المطلوبة.' },
    { lang:'en', id:'docs_forms_90', value:'Clearable single (data-allow-empty)' }, { lang:'ar', id:'docs_forms_90', value:'اختيار مفرد قابل للمسح (data-allow-empty)' },
    { lang:'en', id:'docs_forms_91', value:'<code>data-allow-empty="true"</code> keeps the empty option selectable in the dropdown, so the user can actively re-clear the field. The clear-all "×" also appears once a value is chosen.' }, { lang:'ar', id:'docs_forms_91', value:'تُبقي <code>data-allow-empty="true"</code> الخيار الفارغ قابلًا للاختيار في القائمة المنسدلة، بحيث يمكن للمستخدم مسح الحقل من جديد بشكل فعّال. كما يظهر زر مسح الكل "×" بمجرد اختيار قيمة.' },
    { lang:'en', id:'docs_forms_92', value:'Preselected value (edit mode)' }, { lang:'ar', id:'docs_forms_92', value:'قيمة محددة مسبقًا (وضع التحرير)' },
    { lang:'en', id:'docs_forms_93', value:'An <code>&lt;option selected&gt;</code> carrying the native <code>selected</code> attribute is honored — the factory only force-clears when no option has an explicit <code>selected</code> attribute (a browser default), so saved records repopulate correctly.' }, { lang:'ar', id:'docs_forms_93', value:'يُحترَم <code>&lt;option selected&gt;</code> الذي يحمل سمة <code>selected</code> الأصلية، فالمصنع يفرض المسح فقط عندما لا يحمل أي خيار سمة <code>selected</code> صريحة (وهو سلوك افتراضي للمتصفح)، بحيث تُعاد تعبئة السجلات المحفوظة بشكل صحيح.' },
    { lang:'en', id:'docs_forms_94', value:'<span class="material-symbols-outlined">checklist</span>Multi-select' }, { lang:'ar', id:'docs_forms_94', value:'<span class="material-symbols-outlined">checklist</span>اختيار متعدد' },
    { lang:'en', id:'docs_forms_95', value:'Add <code>multiple</code> (or <code>data-multi="true"</code>). Selections render as removable chips (the <code>remove_button</code> plugin adds a per-chip "×"), and an inline search field is always visible. The right-rail plus icon replaces the chevron. In a WebEOC edit view, restore comma-separated values with <code>repopulateMultiSelect(\'FieldName\', xslValue)</code> — WebEOC does not restore multi-select natively.' }, { lang:'ar', id:'docs_forms_95', value:'أضف <code>multiple</code> (أو <code>data-multi="true"</code>). تُعرض الاختيارات كوسوم قابلة للإزالة (تضيف الإضافة <code>remove_button</code> زر "×" لكل وسم)، ويظل حقل بحث مضمّن مرئيًا دائمًا. تحل أيقونة الزائد في الحافة اليمنى محل السهم. في عرض تحرير WebEOC، استعِد القيم المفصولة بفواصل باستخدام <code>repopulateMultiSelect(\'FieldName\', xslValue)</code>، فإن WebEOC لا يستعيد الاختيار المتعدد بشكل أصلي.' },
    { lang:'en', id:'docs_forms_96', value:'Multiple (chips + remove)' }, { lang:'ar', id:'docs_forms_96', value:'متعدد (وسوم + إزالة)' },
    { lang:'en', id:'docs_forms_97', value:'data-multi="true" (attribute form)' }, { lang:'ar', id:'docs_forms_97', value:'data-multi="true" (صيغة السمة)' },
    { lang:'en', id:'docs_forms_98', value:'<code>data-multi="true"</code> is equivalent to the native <code>multiple</code> attribute. Useful when the markup is generated by a system that will not emit a bare boolean attribute.' }, { lang:'ar', id:'docs_forms_98', value:'تعادل <code>data-multi="true"</code> سمة <code>multiple</code> الأصلية. مفيدة عندما يُنشئ الترميز نظامٌ لا يُصدر سمة منطقية مجردة.' },
    { lang:'en', id:'docs_forms_99', value:'Multi with preselected chips (edit mode)' }, { lang:'ar', id:'docs_forms_99', value:'اختيار متعدد بوسوم محددة مسبقًا (وضع التحرير)' },
    { lang:'en', id:'docs_forms_100', value:'Options carrying <code>selected</code> render as chips on load. For WebEOC, the page-level <code>repopulateMultiSelect</code> helper splits the saved comma-separated string, sets the native value, then calls <code>.sync()</code>.' }, { lang:'ar', id:'docs_forms_100', value:'تُعرض الخيارات التي تحمل <code>selected</code> كوسوم عند التحميل. بالنسبة إلى WebEOC، تقوم الدالة المساعدة <code>repopulateMultiSelect</code> على مستوى الصفحة بتقسيم السلسلة المحفوظة المفصولة بفواصل، وتعيين القيمة الأصلية، ثم استدعاء <code>.sync()</code>.' },
    { lang:'en', id:'docs_forms_101', value:'<span class="material-symbols-outlined">new_label</span>Creatable / tags' }, { lang:'ar', id:'docs_forms_101', value:'<span class="material-symbols-outlined">new_label</span>قابل للإنشاء / وسوم' },
    { lang:'en', id:'docs_forms_102', value:'<code>data-create="true"</code> lets the user type a new value and add it with Enter or Tab. The factory also enables <code>createOnBlur</code>, so tabbing away commits the typed entry automatically. Works on both single and multi selects; multi is the common "tags" pattern.' }, { lang:'ar', id:'docs_forms_102', value:'تتيح <code>data-create="true"</code> للمستخدم كتابة قيمة جديدة وإضافتها بمفتاح Enter أو Tab. كما يُفعّل المصنع <code>createOnBlur</code>، بحيث يؤدي الانتقال بمفتاح Tab إلى تثبيت الإدخال المكتوب تلقائيًا. تعمل مع الاختيار المفرد والمتعدد على حد سواء؛ والاختيار المتعدد هو نمط "الوسوم" الشائع.' },
    { lang:'en', id:'docs_forms_103', value:'Creatable multi (tags)' }, { lang:'ar', id:'docs_forms_103', value:'متعدد قابل للإنشاء (وسوم)' },
    { lang:'en', id:'docs_forms_104', value:'Creatable single' }, { lang:'ar', id:'docs_forms_104', value:'مفرد قابل للإنشاء' },
    { lang:'en', id:'docs_forms_105', value:'The same <code>data-create</code> flag on a single select lets the user commit one free-text value that is not in the option list.' }, { lang:'ar', id:'docs_forms_105', value:'تتيح راية <code>data-create</code> نفسها على اختيار مفرد للمستخدم تثبيت قيمة نصية حرة واحدة غير موجودة في قائمة الخيارات.' },
    { lang:'en', id:'docs_forms_106', value:'<span class="material-symbols-outlined">cloud_download</span>Remote / autocomplete (data-src="api")' }, { lang:'ar', id:'docs_forms_106', value:'<span class="material-symbols-outlined">cloud_download</span>عن بُعد / إكمال تلقائي (data-src="api")' },
    { lang:'en', id:'docs_forms_107', value:'<code>data-src="api"</code> turns the control into a remote autocomplete. The factory fetches <code>data-url?&lt;data-url-param&gt;=&lt;query&gt;</code> and maps each row through <code>data-value-field</code> / <code>data-label-field</code>. <code>data-preload="true"</code> loads once immediately; <code>data-preload="focus"</code> loads on first focus; omit to load only on keystroke. Placeholder injection and force-clear are skipped for API selects (options arrive asynchronously).' }, { lang:'ar', id:'docs_forms_107', value:'<code>data-src="api"</code> تحوّل عنصر التحكم إلى إكمال تلقائي عن بُعد. يجلب المصنع <code>data-url?&lt;data-url-param&gt;=&lt;query&gt;</code> ويربط كل صف عبر <code>data-value-field</code> / <code>data-label-field</code>. تُحمّل <code>data-preload="true"</code> مرة واحدة فورًا؛ وتُحمّل <code>data-preload="focus"</code> عند أول تركيز؛ واحذفها للتحميل عند الكتابة فقط. يُتخطى إدراج العنصر النائب والمسح القسري لقوائم اختيار الـ API (تصل الخيارات بشكل غير متزامن).' },
    { lang:'en', id:'docs_forms_108', value:'Live endpoint required' }, { lang:'ar', id:'docs_forms_108', value:'مطلوب نقطة نهاية نشطة' },
    { lang:'en', id:'docs_forms_109', value:'This demo points at a placeholder <code>data-url</code>. With no reachable endpoint the control renders and searches, but returns no rows. Point <code>data-url</code> at a real JSON endpoint that echoes an array of <code>{ id, text }</code> objects to see results.' }, { lang:'ar', id:'docs_forms_109', value:'يشير هذا العرض التوضيحي إلى <code>data-url</code> نائبة. بدون نقطة نهاية يمكن الوصول إليها، يُعرض عنصر التحكم ويبحث، لكنه لا يُرجع أي صفوف. وجّه <code>data-url</code> إلى نقطة نهاية JSON حقيقية تعيد مصفوفة من كائنات <code>{ id, text }</code> لرؤية النتائج.' },
    { lang:'en', id:'docs_forms_110', value:'Remote search — load on keystroke' }, { lang:'ar', id:'docs_forms_110', value:'بحث عن بُعد: التحميل عند الكتابة' },
    { lang:'en', id:'docs_forms_111', value:'Remote — preload on focus' }, { lang:'ar', id:'docs_forms_111', value:'عن بُعد: التحميل المسبق عند التركيز' },
    { lang:'en', id:'docs_forms_112', value:'<code>data-preload="focus"</code> fetches the initial result set the first time the control is focused, so an empty query already shows options.' }, { lang:'ar', id:'docs_forms_112', value:'تجلب <code>data-preload="focus"</code> مجموعة النتائج الأولية عند تركيز عنصر التحكم لأول مرة، بحيث يعرض الاستعلام الفارغ خيارات بالفعل.' },
    { lang:'en', id:'docs_forms_113', value:'<span class="material-symbols-outlined">segment</span>Optgroups' }, { lang:'ar', id:'docs_forms_113', value:'<span class="material-symbols-outlined">segment</span>مجموعات الخيارات' },
    { lang:'en', id:'docs_forms_114', value:'Native <code>&lt;optgroup label="…"&gt;</code> elements are honored — Tom Select renders each group with a pinned <code>optgroup-header</code>. Works with single and multi. No extra attributes are needed.' }, { lang:'ar', id:'docs_forms_114', value:'تُحترَم عناصر <code>&lt;optgroup label="…"&gt;</code> الأصلية، فيعرض Tom Select كل مجموعة برأس <code>optgroup-header</code> مثبّت. تعمل مع الاختيار المفرد والمتعدد. لا حاجة إلى سمات إضافية.' },
    { lang:'en', id:'docs_forms_115', value:'<span class="material-symbols-outlined">palette</span>Custom option / item renderers' }, { lang:'ar', id:'docs_forms_115', value:'<span class="material-symbols-outlined">palette</span>أدوات عرض مخصصة للخيار / العنصر' },
    { lang:'en', id:'docs_forms_116', value:'Register a render template with <code>TomSelectFactory.registerTemplate(name, def)</code> <strong>before</strong> <code>init()</code>, then point a select at it with <code>data-render="name"</code>. Tom Select copies every <code>data-*</code> attribute from each <code>&lt;option&gt;</code> into the option data object, so the template can render rich rows. Supported keys: <code>option</code>, <code>item</code>, <code>option_create</code>, <code>no_results</code>, <code>not_loading</code>, <code>optgroup</code>, <code>optgroup_header</code>, <code>loading</code>, <code>dropdown</code>. The agency CSS ships <code>.ts-person-option</code> / <code>.ts-person-name</code> / <code>.ts-person-meta</code> for this pattern.' }, { lang:'ar', id:'docs_forms_116', value:'سجّل قالب عرض باستخدام <code>TomSelectFactory.registerTemplate(name, def)</code> <strong>قبل</strong> <code>init()</code>، ثم وجّه قائمة اختيار إليه عبر <code>data-render="name"</code>. ينسخ Tom Select كل سمة <code>data-*</code> من كل <code>&lt;option&gt;</code> إلى كائن بيانات الخيار، بحيث يستطيع القالب عرض صفوف غنية. المفاتيح المدعومة: <code>option</code> و<code>item</code> و<code>option_create</code> و<code>no_results</code> و<code>not_loading</code> و<code>optgroup</code> و<code>optgroup_header</code> و<code>loading</code> و<code>dropdown</code>. يوفّر CSS الوكالة <code>.ts-person-option</code> / <code>.ts-person-name</code> / <code>.ts-person-meta</code> لهذا النمط.' },
    { lang:'en', id:'docs_forms_117', value:'<span class="material-symbols-outlined">account_tree</span>Dependent / cascading selects' }, { lang:'ar', id:'docs_forms_117', value:'<span class="material-symbols-outlined">account_tree</span>قوائم الاختيار التابعة / المتسلسلة' },
    { lang:'en', id:'docs_forms_118', value:'Two wiring styles. In WebEOC the board engine swaps the child\'s <code>&lt;option&gt;</code> list when the parent changes — mark the child with <code>data-parent="ParentName"</code> (or <code>parent="…"</code>) and the factory rebuilds the child from the currently visible native options. Outside WebEOC, wire <code>data-on-change="GlobalFn"</code> on the parent to a function that rebuilds the child options and calls <code>TomSelectFactory.get(\'child\').clearOptions()</code> then <code>.sync()</code>. The live demo below uses the <code>data-on-change</code> style.' }, { lang:'ar', id:'docs_forms_118', value:'أسلوبان للربط. في WebEOC، يبدّل محرك اللوحة قائمة <code>&lt;option&gt;</code> الخاصة بالعنصر التابع عند تغيّر العنصر الأصل، فعلّم العنصر التابع بـ <code>data-parent="ParentName"</code> (أو <code>parent="…"</code>) ويعيد المصنع بناء العنصر التابع من الخيارات الأصلية المرئية حاليًا. خارج WebEOC، اربط <code>data-on-change="GlobalFn"</code> على العنصر الأصل بدالة تعيد بناء خيارات العنصر التابع وتستدعي <code>TomSelectFactory.get(\'child\').clearOptions()</code> ثم <code>.sync()</code>. يستخدم العرض التوضيحي الحي أدناه أسلوب <code>data-on-change</code>.' },
    { lang:'en', id:'docs_forms_119', value:'<span class="material-symbols-outlined">vertical_split</span>Dropdown slots (header / footer)' }, { lang:'ar', id:'docs_forms_119', value:'<span class="material-symbols-outlined">vertical_split</span>فتحات القائمة المنسدلة (الرأس / التذييل)' },
    { lang:'en', id:'docs_forms_120', value:'Mount arbitrary markup as a pinned header and/or footer inside the dropdown. Stage a hidden <code>&lt;div class="ts-dropdown-slot"&gt;</code> in the page and point the select at it with <code>data-dropdown-header="#id"</code> / <code>data-dropdown-footer="#id"</code>. The factory <em>moves</em> the node (not a clone, so ids stay unique) into the dropdown and shields it from Tom Select\'s select/close handlers, so controls inside the slot stay interactive. Pair with <code>data-stay-open="true"</code> so picking an option does not close the dropdown while the user is also using the slot controls. Slots are also mountable manually via <code>TomSelectFactory.mountDropdownSlots(ts, el)</code>.' }, { lang:'ar', id:'docs_forms_120', value:'ثبّت أي ترميز كرأس و/أو تذييل مثبّت داخل القائمة المنسدلة. جهّز <code>&lt;div class="ts-dropdown-slot"&gt;</code> مخفيًا في الصفحة ووجّه قائمة الاختيار إليه عبر <code>data-dropdown-header="#id"</code> / <code>data-dropdown-footer="#id"</code>. <em>ينقل</em> المصنع العقدة (وليس نسخة عنها، لذا تبقى المعرّفات فريدة) إلى القائمة المنسدلة ويحميها من معالِجات الاختيار/الإغلاق في Tom Select، بحيث تبقى عناصر التحكم داخل الفتحة تفاعلية. اقرنها بـ <code>data-stay-open="true"</code> بحيث لا يؤدي اختيار خيار إلى إغلاق القائمة المنسدلة بينما يستخدم المستخدم عناصر تحكم الفتحة أيضًا. يمكن أيضًا تثبيت الفتحات يدويًا عبر <code>TomSelectFactory.mountDropdownSlots(ts, el)</code>.' },
    { lang:'en', id:'docs_forms_121', value:'Mount once' }, { lang:'ar', id:'docs_forms_121', value:'التثبيت مرة واحدة' },
    { lang:'en', id:'docs_forms_122', value:'The slot node is consumed into the dropdown, so a select that is destroyed and re-initialized loses its slot. Mount already-initialized controls.' }, { lang:'ar', id:'docs_forms_122', value:'تُستهلك عقدة الفتحة داخل القائمة المنسدلة، لذا تفقد قائمة الاختيار التي يتم إتلافها وإعادة تهيئتها فتحتها. ثبّت عناصر التحكم المهيّأة بالفعل.' },
    { lang:'en', id:'docs_forms_123', value:'Header slot + footer slot (stay-open)' }, { lang:'ar', id:'docs_forms_123', value:'فتحة الرأس + فتحة التذييل (البقاء مفتوحًا)' },
    { lang:'en', id:'docs_forms_124', value:'<span class="material-symbols-outlined">bolt</span>Change callback (data-on-change)' }, { lang:'ar', id:'docs_forms_124', value:'<span class="material-symbols-outlined">bolt</span>رد نداء التغيير (data-on-change)' },
    { lang:'en', id:'docs_forms_125', value:'<code>data-on-change="GlobalFn"</code> calls <code>window.GlobalFn(value, key, instance)</code> on every change — the value, the instance key, and the live Tom Select instance. Use it to drive dependent UI without touching the factory internals.' }, { lang:'ar', id:'docs_forms_125', value:'تستدعي <code>data-on-change="GlobalFn"</code> الدالة <code>window.GlobalFn(value, key, instance)</code> عند كل تغيير: القيمة، ومفتاح النسخة، ونسخة Tom Select النشطة. استخدمها لتشغيل واجهة مستخدم تابعة دون المساس بالأجزاء الداخلية للمصنع.' },
    { lang:'en', id:'docs_forms_126', value:'<span class="material-symbols-outlined">open_in_full</span>Dropdown parent (data-dropdown-parent)' }, { lang:'ar', id:'docs_forms_126', value:'<span class="material-symbols-outlined">open_in_full</span>العنصر الأصل للقائمة المنسدلة (data-dropdown-parent)' },
    { lang:'en', id:'docs_forms_127', value:'The dropdown teleports to <code>&lt;body&gt;</code> by default so it is never clipped by an <code>overflow:hidden</code> ancestor. Override the mount target with <code>data-dropdown-parent="&lt;selector&gt;"</code> when the dropdown must live inside a specific scroll container or modal.' }, { lang:'ar', id:'docs_forms_127', value:'تنتقل القائمة المنسدلة إلى <code>&lt;body&gt;</code> افتراضيًا بحيث لا يقتطعها أبدًا عنصر أصل يحمل <code>overflow:hidden</code>. تجاوز هدف التثبيت باستخدام <code>data-dropdown-parent="&lt;selector&gt;"</code> عندما يجب أن توجد القائمة المنسدلة داخل حاوية تمرير أو نافذة منبثقة محددة.' },
    { lang:'en', id:'docs_forms_128', value:'<span class="material-symbols-outlined">block</span>States — disabled &amp; readonly' }, { lang:'ar', id:'docs_forms_128', value:'<span class="material-symbols-outlined">block</span>الحالات: معطّل وللقراءة فقط' },
    { lang:'en', id:'docs_forms_129', value:'Disabled (native <code>disabled</code> attribute, or <code>TomSelectFactory.disable(\'key\')</code>) renders at reduced opacity, fully inert with no tab stop. Readonly (add <code>.is-readonly</code> to the <code>.ts-wrapper</code> after init) matches the form-control readonly style: dashed border, muted surface, text still selectable and copyable, and no dropdown opens.' }, { lang:'ar', id:'docs_forms_129', value:'يُعرض الوضع المعطّل (سمة <code>disabled</code> الأصلية، أو <code>TomSelectFactory.disable(\'key\')</code>) بعتامة منخفضة، خامل تمامًا دون نقطة توقف للتنقل بمفتاح Tab. أما الوضع للقراءة فقط (أضف <code>.is-readonly</code> إلى <code>.ts-wrapper</code> بعد التهيئة) فيطابق نمط عنصر التحكم للقراءة فقط: حدود متقطعة، وسطح باهت، ونص يبقى قابلًا للتحديد والنسخ، ولا تُفتح أي قائمة منسدلة.' },
    { lang:'en', id:'docs_forms_130', value:'On this page' }, { lang:'ar', id:'docs_forms_130', value:'في هذه الصفحة' }
  ]);
})();
